// La fanciulla del West, complete Act 3; source: user-supplied 1910 Italian libretto PDF.
// All directions and spoken/sung text retained in source order. English: unreviewed assistant draft.
export const fanciullaActThreeScenes = [{"number":1,"originalHeading":"Atto terzo","translatedHeading":"Act III","summary":"Johnson faces execution in the forest until Minnie pleads for his life and leaves with him.","sections":[{"type":"Passage","listeningLandmark":true,"routeItem":0,"originalTitle":"Ve lo giuro, sceriffo","translatedTitle":"I swear to you, sheriff","threeLineOutline":true,"sourceTitlesOnly":true,"participants":["Nick"],"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":0,"sourcePage":42,"original":"(La grande Selva Californiana. Lembo estremo della selva sul degradare lento di un contrafforte della Sierra. Uno spiazzo circondato da tronchi enormi, dritti e nudi delle conifere secolari, che formano intorno come un colonnato gigantesco. Nel fondo, dove la selva s’infoltisce sempre più, s’apre un sentiero che s’interna tra i tronchi: qual e là appaiono picchi nevosi altissimi di montagne. Per lo spiazzo, che è come un bivacco dei minatori, sono stesi dei grandi tronchi abbattuti, che servono da sedile; accanto ad uno di questi arde un fuoco alimentato da grossi rami. nella luce incerta della prim’alba la grandiosa fuga dei tronchi rossigni muore in un velo folto di nebbia. Da un lato, nell’ampio tronco di un albero colossale, è scavato un ripostiglio di arnesi da minatore – da un altro lato, tra felci ed arbusti, legato ad un ramo, un cavallo insellato – a lui vicino Ashby addormentato – altri due cavalli, più nel fondo, vicino a due uomini addormentati – sul davanti, vicino ad Ashby, altri tre uomini dormono sdraiati a terra – Billy dorme, a destra, la testa appoggiata a un tronco d’albero – accanto a lui una corda già pronta per il laccio.\nRance è seduto a sinistra presso il fuoco, con gli abiti in disordine, il viso stanco e sconvolto, i capelli arruffati. Nick, pensieroso, è seduto in faccia a rance. Nessun rumore turba il silenzio dell’alba invernale)\n(attizzando il fuoco con la punta dello stivale; sottovoce, cupamente)","translation":"The great Californian forest, at the edge of a gently descending spur of the Sierra. An open space surrounded by the immense, straight, bare trunks of ancient conifers, forming a giant colonnade. In the thickening forest beyond, a path winds among the trees; here and there very high snow-covered peaks appear. Felled trunks provide seats around a fire of large branches. In the uncertain light of early dawn, the reddish trunks fade into thick mist. A hollow in a colossal tree holds mining tools; nearby, among ferns and shrubs, a saddled horse stands tethered to a branch. Ashby sleeps beside it, while farther back two more horses stand near two sleeping men. Three other men lie asleep near Ashby; Billy sleeps on the right with his head against a tree, a prepared noose beside him.\nRance sits dishevelled and exhausted by the fire. Nick sits opposite, deep in thought. Nothing disturbs the silence of this winter dawn. Nick stirs the\nfire with his boot, speaking quietly and grimly."},{"speaker":"NICK","speakerTranslation":"Nick","literalText":true,"sourceTurn":1,"sourcePage":42,"original":"Ve lo giuro, sceriffo:\ndarei tutte le mance\ndi dieci settimane\npur di tornare indietro d’una sola,\nquando questo dannato\nJohnson della malora\nnon ci s’era cacciato ancor fra i piedi!","translation":"I swear to you,\nsheriff:\nI would give all the tips\nfrom ten weeks just to go\nback one week,\nto when that cursed\nJohnson had not yet crossed our path!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":2,"sourcePage":42,"original":"(con rabbia, cupamente)","translation":"(Angrily, darkly.)"}]},{"type":"Passage","listeningLandmark":true,"routeItem":1,"originalTitle":"Maledetto cane!","translatedTitle":"Damned dog!","threeLineOutline":true,"sourceTitlesOnly":true,"participants":["Rance","Nick"],"turns":[{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":3,"sourcePage":42,"original":"Maledetto cane!\nParea ferito a morte…\nE pensar che da allora,\nmentre noi si gelava fra la neve,\nè stato là, scaldato\ndal respiro di Minnie, accarezzato, \nbaciato…","translation":"That damned dog!\nHe seemed wounded to death...\nAnd to think that\nall this time, while we froze in the snow,\nhe has been there,\nwarmed by Minnie's breath,\ncaressed and kissed..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":4,"sourcePage":42,"original":"(con uno scatto di protesta; a bassa voce)","translation":"(With a sudden protest, quietly.)"},{"speaker":"NICK","speakerTranslation":"Nick","literalText":true,"sourceTurn":5,"sourcePage":42,"original":"Oh, Rance!…","translation":"Oh, Rance!..."},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":6,"sourcePage":42,"original":"Un ladro del suo stampo!\nAvrei voluto a tutti\ngridar quel che sapevo…","translation":"A thief of his kind!\nI wanted to shout\nto everyone what I knew..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":7,"sourcePage":42,"original":"(con approvazione un po’ canzonatoria; con calma)","translation":"(Calmly, with slightly teasing approval.)"},{"speaker":"NICK","speakerTranslation":"Nick","literalText":true,"sourceTurn":8,"sourcePage":42,"original":"E non l’avete fatto.\nÈ stato proprio un tratto \ncavalleresco…","translation":"And you did not.\nIt was truly a chivalrous\nthing to do..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":9,"sourcePage":42,"original":"(sogghignando amaramente, fra sé)","translation":"(Bitterly sneering to himself.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":10,"sourcePage":42,"original":"Ah, sì!","translation":"Oh, yes!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":11,"sourcePage":42,"original":"(a Nick, con rancore sostenuto)","translation":"(To Nick, with sustained resentment.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":12,"sourcePage":42,"original":"Ma che ci vede, dimmi,\nche ci trova la nostra Minnie\nin quel fantoccio?…","translation":"But tell me,\nwhat does our Minnie see in that puppet?\nWhat can she find in him?"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":13,"sourcePage":42,"original":"(sorridendo, con fare accorto)","translation":"(Smiling shrewdly.)"},{"speaker":"NICK","speakerTranslation":"Nick","literalText":true,"sourceTurn":14,"sourcePage":42,"original":"Mah! Qualcosa ci vedrà!…","translation":"Well, she must see something in him!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":15,"sourcePage":42,"original":"(con comica filosofia)","translation":"(With comic philosophy.)"},{"speaker":"NICK","speakerTranslation":"Nick","literalText":true,"sourceTurn":16,"sourcePage":42,"original":"Amore, amore!\nParadiso ed inferno, è quel che è:","translation":"Love, love!\nParadise and hell, that's what it is:"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":17,"sourcePage":42,"original":"(comincia ad albeggiare)","translation":"(Day begins to break.)"},{"speaker":"NICK","speakerTranslation":"Nick","literalText":true,"sourceTurn":18,"sourcePage":42,"original":"tutto il dannato mondo s’innamora!\nAnche per Minnie è giunta oggi quell’ora.","translation":"the whole damned world falls in love!\nAnd today Minnie's hour has come too."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":19,"sourcePage":42,"original":"(A poco a poco la luce del giorno va rischiarando la scena. A un tratto un clamore lontano, vago e confuso giunge dalla montagna. Ashby si sveglia, balza in piedi di scatto e va verso il fondo. Anche Rance e Nick si alzano e vengono nel mezzo della scena)","translation":"(Daylight gradually brightens the stage. Suddenly vague, confused distant shouts come from the mountain. Ashby wakes, springs to his feet, and goes to the back. Rance and Nick also rise and move to the middle of the stage.)"}]},{"type":"Passage","listeningLandmark":true,"routeItem":2,"originalTitle":"Ah!… Ah!… Urrah, ragazzi!","translatedTitle":"Ah!… Ah!… Hurrah, boys!","threeLineOutline":true,"sourceTitlesOnly":true,"participants":["Distant voices","Ashby","Approaching voices","Rance","Nearby voices","Miners","Offstage voices","Nick","Others","Voices","Joe","Harry","Bello","Sonora","All","Trin","Happy"],"turns":[{"speaker":"VOCI LONTANE","speakerTranslation":"Distant voices","literalText":true,"sourceTurn":20,"sourcePage":43,"original":"Ah!… Ah!… Ah!…","translation":"Ah!... Ah!... Ah!..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":21,"sourcePage":43,"original":"(Gli uomini sdraiati a terra si svegliano e rimontano la scena, dirigendosi al fondo e sui lati: i due cavalieri si svegliano anch’essi e si tengono pronti a montare in sella. Billy si sveglia, e senza mostrare la minima attenzione agli altri, leva di tasca un giuoco di carte e si mette, con grande lentezza, a fare un solitario fumando la pipa.)\n(all’udire le voci grida, scendendo in mezzo alla scena)","translation":"(The men lying on the ground wake and go upstage and to the sides; the horsemen wake and prepare to mount. Billy wakes and, paying no attention to anyone, slowly takes out a deck of cards and plays solitaire while smoking his pipe. Ashby shouts at\nthe sound of the voices and comes downstage.)"},{"speaker":"ASHBY","speakerTranslation":"Ashby","literalText":true,"sourceTurn":22,"sourcePage":43,"original":"Urrah, ragazzi!… Urrah!… urrah!","translation":"Hurrah, boys!... Hurrah!... Hurrah!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":23,"sourcePage":43,"original":"(rivolto a Rance)","translation":"(Addressing Rance.)"},{"speaker":"ASHBY","speakerTranslation":"Ashby","literalText":true,"sourceTurn":24,"sourcePage":43,"original":"Sceriffo, avete udito?\nN’ero certo!\nHan trovato il bandito!…\nUna buona giornata per Wells Fargo!…","translation":"Sheriff, did you hear?\nI knew it!\nThey have found the bandit!...\nA fine day for Wells Fargo!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":25,"sourcePage":43,"original":"(da vari punti)","translation":"(From several directions.)"},{"speaker":"VOCI PIÙ VICINE","speakerTranslation":"Approaching voices","literalText":true,"sourceTurn":26,"sourcePage":43,"original":"Holla.!… Holla!… Holla!…\nAh!… Ah!… Ah!…","translation":"Holla!... Holla!... Holla!... Ah!...\nAh!... Ah!..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":27,"sourcePage":43,"original":"(a Rance)","translation":"(To Rance.)"},{"speaker":"ASHBY","speakerTranslation":"Ashby","literalText":true,"sourceTurn":28,"sourcePage":43,"original":"Non udite? Ah, questa volta\nnon mi sfuggi, brigante!","translation":"Can't you hear? Ah,\nthis time you won't escape me, brigand!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":29,"sourcePage":43,"original":"(amaro)","translation":"(Bitterly.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":30,"sourcePage":43,"original":"Siete più fortunato di me!","translation":"You are luckier than I!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":31,"sourcePage":43,"original":"(osservandolo, stringendo gli occhi con uno sguardo indagatore)","translation":"(Studying him with a searching, narrowed gaze.)"},{"speaker":"ASHBY","speakerTranslation":"Ashby","literalText":true,"sourceTurn":32,"sourcePage":43,"original":"Da quella notte là, alla “Polka”\nnon vi ho capito più, \nsceriffo…","translation":"Since that night at the Polka,\nI have no longer understood you,\nsheriff..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":33,"sourcePage":43,"original":"(Rance alza le spalle e non risponde).","translation":"(Rance shrugs and says nothing.)"},{"speaker":"VOCI VICINISSIME","speakerTranslation":"Nearby voices","literalText":true,"sourceTurn":34,"sourcePage":43,"original":"Holla.!… Holla!… Holla!…","translation":"Holla!... Holla!... Holla!..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":35,"sourcePage":43,"original":"(Un gruppo di uomini, seguiti da due cavalieri, sbucano correndo dal fondo a destra, traversando la scena con un movimento aggirante. Alcuni hanno in pugno coltellacci e pistole, altri delle vanghe e dei bastoni. Gridano tutti confusamente, come cani che inseguano un selvatico.)\n(lanciandosi verso di loro)","translation":"(A group of men followed by two horsemen bursts in running from the rear right and crosses the stage in a sweeping movement. Some brandish knives and pistols; others carry spades and clubs. They all shout wildly like hounds in pursuit of prey.\nAshby rushes towards them.)"},{"speaker":"ASHBY","speakerTranslation":"Ashby","literalText":true,"sourceTurn":36,"sourcePage":43,"original":"Holla!…\nFermi tutti, perdio!","translation":"Holla!...\nEveryone stop, damn it!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":37,"sourcePage":43,"original":"(La folla degli inseguitori si ferma un istante, volgendosi alle grida)","translation":"(The pursuing crowd halts for a moment and turns at the shouting.)"},{"speaker":"ASHBY","speakerTranslation":"Ashby","literalText":true,"sourceTurn":38,"sourcePage":43,"original":"Giù le armi! Dev’esser preso vivo!","translation":"Lower your weapons! He must be taken alive!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":39,"sourcePage":43,"original":"(ad un gruppo di altri che sopraggiungono da sinistra))","translation":"(To another group arriving from the left.)"},{"speaker":"ASHBY","speakerTranslation":"Ashby","literalText":true,"sourceTurn":40,"sourcePage":43,"original":"Dov’è?","translation":"Where is he?"},{"speaker":"MINATORI","speakerTranslation":"Miners","literalText":true,"sourceTurn":41,"sourcePage":43,"original":"S’insegue…","translation":"We're after him..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":42,"sourcePage":43,"original":"(indicando la direzione)","translation":"(Pointing the way.)"},{"speaker":"MINATORI","speakerTranslation":"Miners","literalText":true,"sourceTurn":43,"sourcePage":43,"original":"Per di qua…","translation":"This way..."},{"speaker":"ASHBY","speakerTranslation":"Ashby","literalText":true,"sourceTurn":44,"sourcePage":43,"original":"Dove?","translation":"Where?"},{"speaker":"MINATORI","speakerTranslation":"Miners","literalText":true,"sourceTurn":45,"sourcePage":43,"original":"Di là, di là dal monte!\nIl bosco fino a valle\nè già tutto in allarme\nAshby, a fra poco! \nAddio!","translation":"There, beyond the mountain!\nThe forest down to the\nvalley is already on alert.\nAshby, see you soon!\nFarewell!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":46,"sourcePage":43,"original":"(balzando in sella al cavallo)","translation":"(Leaping into the saddle.)"},{"speaker":"ASHBY","speakerTranslation":"Ashby","literalText":true,"sourceTurn":47,"sourcePage":43,"original":"Vengo con voi!","translation":"I'm coming with you!"},{"speaker":"MINATORI","speakerTranslation":"Miners","literalText":true,"sourceTurn":48,"sourcePage":43,"original":"Urrah!… Urrah!… Urrah!…","translation":"Hurrah!... Hurrah!... Hurrah!..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":49,"sourcePage":43,"original":"(Ashby saluta con la mano Rance e Nick e si allontana al trotto preceduto dai minatori e seguito da quattro cavalieri.)","translation":"(Ashby waves farewell to Rance and Nick and rides off at a trot, preceded by the miners and followed by four horsemen.)"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":50,"sourcePage":44,"original":"(indicando la direzione)","translation":"(Pointing the direction.)"},{"speaker":"MINATORI","speakerTranslation":"Miners","literalText":true,"sourceTurn":51,"sourcePage":44,"original":"Per di qua! \nPer di qua!","translation":"This way!\nThis way!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":52,"sourcePage":44,"original":"(Il gruppo scompare fra gli alberi. Nick e Rance rimangono soli)\n(levando le braccia, come per rivolgersi verso la casa di Minnie, in uno scatto di gioia crudele)","translation":"(The group disappears among the trees. Nick and Rance are alone.\nRance raises his arms as if addressing Minnie's home, in a burst of cruel delight.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":53,"sourcePage":44,"original":"Ora piangi tu, o Minnie! or piangi tu!","translation":"Now you will weep, Minnie! Now you will weep!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":54,"sourcePage":44,"original":"(Nick va verso il fondo e guarda ansioso, a destra e a sinistra)","translation":"(Nick goes to the back and looks anxiously right and left.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":55,"sourcePage":44,"original":"Per te soltanto\nmi son disfatto per notti di pianto,\ne tu ridevi alla miseria mia!\nOra quel pianto mi trabocca in riso!\nMinnie, ora piangi tu… che m’hai deriso!\nQuegli che amasti non ritornerà:\nLa corda è pronta che l’impiccherà!","translation":"For you alone\nI spent nights torn apart by weeping,\nwhile you laughed at my misery!\nNow those tears overflow as laughter! Minnie,\nnow you will weep, you who mocked me!\nThe man you loved will never return:\nthe rope is ready to hang him!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":56,"sourcePage":44,"original":"(Si getta a sedere sul tronco riverso, serbando sul viso il suo riso cattivo. Alcuni minatori entrano in scena correndo da destra)\n(sempre più vicine)","translation":"(He throws himself onto a fallen log, retaining his cruel smile. Some miners run in from the right.\nTheir voices draw nearer.)"},{"speaker":"VOCI INTERNE","speakerTranslation":"Offstage voices","literalText":true,"sourceTurn":57,"sourcePage":44,"original":"Ah!… Ah!…","translation":"Ah!... Ah!..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":58,"sourcePage":44,"original":"(ai più prossimi, interrogandoli)","translation":"(Questioning the nearest men.)"},{"speaker":"NICK","speakerTranslation":"Nick","literalText":true,"sourceTurn":59,"sourcePage":44,"original":"Dite!… Dite!","translation":"Tell me!... Tell me!"},{"speaker":"MINATORI","speakerTranslation":"Miners","literalText":true,"sourceTurn":60,"sourcePage":44,"original":"È rinchiuso!\nAvanti, avanti!\nFra poco!","translation":"He is cornered!\nOnward,\nonward! Soon!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":61,"sourcePage":44,"original":"(escono di scena a sinistra correndo)","translation":"(They run off to the left.)"},{"speaker":"MINATORI","speakerTranslation":"Miners","literalText":true,"sourceTurn":62,"sourcePage":44,"original":"Avanti, avanti!","translation":"Onward, onward!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":63,"sourcePage":44,"original":"(La muta furiosa si è allontanata. Nick riprende la sua passeggiata, cogitabondo, e si ferma vicino a Rance, che è ancora seduto, chiuso e torvo)","translation":"(The furious hunting party has moved away. Nick resumes pacing thoughtfully, then stops near Rance, who remains seated, dark and withdrawn.)"},{"speaker":"VOCI INTERNE","speakerTranslation":"Offstage voices","literalText":true,"sourceTurn":64,"sourcePage":44,"original":"Hurrah!!","translation":"Hurrah!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":65,"sourcePage":44,"original":"(a Nick, senza fermarsi)","translation":"(To Nick, without stopping.)"},{"speaker":"ALTRI","speakerTranslation":"Others","literalText":true,"sourceTurn":66,"sourcePage":44,"original":"Fra poco!","translation":"Soon!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":67,"sourcePage":44,"original":"(che sopraggiungono, incitando gli altri alla corsa) ","translation":"(Arriving and urging the others to run.)"},{"speaker":"ALTRI","speakerTranslation":"Others","literalText":true,"sourceTurn":68,"sourcePage":44,"original":"Avanti!…","translation":"Onward!..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":69,"sourcePage":44,"original":"(La muta furiosa si è allontanata. Nick riprende la sua passeggiata, cogitabondo, poi si ferma vicino a Rance, che è ancora seduto, chiuso e torvo)","translation":"(The furious pack has moved away. Nick resumes pacing, then stops beside Rance, who still sits brooding.)"},{"speaker":"VOCI INTERNE","speakerTranslation":"Offstage voices","literalText":true,"sourceTurn":70,"sourcePage":44,"original":"Urrah!…","translation":"Hurrah!..."},{"speaker":"NICK","speakerTranslation":"Nick","literalText":true,"sourceTurn":71,"sourcePage":44,"original":"Sceriffo, avete udito?","translation":"Sheriff, did you hear?"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":72,"sourcePage":44,"original":"(senza rispondergli, con ira sorda, guardando in terra)","translation":"(Without answering, looking at the ground with muffled anger.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":73,"sourcePage":44,"original":"Johnson… di Sacramento,\nun demonio t’assiste! Ma, perdio!…\nse ti prendono al laccio\ne non ti faccio\nscontare ogni tormento,\npuoi sputarmi sul viso!…","translation":"Johnson of Sacramento, a devil must\nbe protecting you! But, by God,\nif they catch you in the noose and\nI do not\nmake you pay with every torment,\nyou may spit in my face!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":74,"sourcePage":44,"original":"(Giunge da sinistra un’altra turba urlante d’uomini a piedi. Vedendo Rance e Nick sì fermano. Harry e Bello sono avanti a tutti)","translation":"(Another shouting crowd approaches on foot from the left. They stop when they see Rance and Nick; Harry and Bello are in front.)"},{"speaker":"VOCI E JOE","speakerTranslation":"Voices, Joe","literalText":true,"sourceTurn":75,"sourcePage":44,"original":"Fugge! Fugge!…","translation":"He's escaping! He's escaping!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":76,"sourcePage":44,"original":"(scattando in piedi e slanciandosi verso Harry)","translation":"(Springing up and lunging toward Harry.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":77,"sourcePage":44,"original":"Ah, perdio!","translation":"Ah, damn it!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":78,"sourcePage":44,"original":"(Alcuni si arrestano all’esclamazione di Rance, ma con gesti e con movimenti debbono rendere l’azione viva e febbrile seguendo i diversi dettagli del racconto di Harry e Bello.)","translation":"(Some men stop at Rance's cry, but their gestures must keep the action lively and feverish as Harry and Bello tell the details.)"},{"speaker":"HARRY","speakerTranslation":"Harry","literalText":true,"sourceTurn":79,"sourcePage":44,"original":"E montato a cavallo!…","translation":"He mounted a horse!..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":80,"sourcePage":45,"original":"(facendosi in mezzo alla turba in clamore, gridando)","translation":"(Forcing his way into the shouting crowd.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":81,"sourcePage":45,"original":"Come? Dove?…","translation":"How? Where?..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":82,"sourcePage":45,"original":"(ansando)","translation":"(Panting.)"},{"speaker":"HARRY, JOE E BELLO","speakerTranslation":"Harry, Joe, Bello","literalText":true,"sourceTurn":83,"sourcePage":45,"original":"Alla Bota \ngià un uomo gli era sopra…","translation":"At the Bota,\na man was already on top of him..."},{"speaker":"HARRY E JOE","speakerTranslation":"Harry, Joe","literalText":true,"sourceTurn":84,"sourcePage":45,"original":"Sembrava ormai spacciato!…","translation":"It looked as though he was finished!..."},{"speaker":"MINATORI","speakerTranslation":"Miners","literalText":true,"sourceTurn":85,"sourcePage":45,"original":"Non gli restava scampo!\nGià l’aveva acciuffato pei capelli…","translation":"There was no escape!\nHe had already been seized by the hair..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":86,"sourcePage":45,"original":"(Un altro gruppo di uomini viene correndo da sinistra)","translation":"(Another band of men comes running from the left.)"},{"speaker":"MINATORI","speakerTranslation":"Miners","literalText":true,"sourceTurn":87,"sourcePage":45,"original":"Quand’ecco…","translation":"When suddenly..."},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":88,"sourcePage":45,"original":"Racconta…","translation":"Tell us..."},{"speaker":"HARRY, JOE E BELLO","speakerTranslation":"Harry, Joe, Bello","literalText":true,"sourceTurn":89,"sourcePage":45,"original":"Quand’ecco il maledetto\ncon un colpo lo sbalza\ngiù d’arcioni, s’afferra\nai crini, balza in sella,\nsprona, e… via come un lampo!","translation":"Then the damned fellow struck his pursuer,\nthrew him\nout of the saddle,\ngrabbed the horse's mane, sprang up,\nspurred on, and vanished like lightning!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":90,"sourcePage":45,"original":"(Nel fondo passano al galoppo quattro cavalieri e scompaiono a destra)\n(varie)","translation":"(Four horsemen gallop across the rear and disappear to the right.\nVarious voices.)"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":91,"sourcePage":45,"original":"Gli uomini di Wells Fargo\nl’inseguono a cavallo!\nAshby è con la sua gente!\nGli son tutti alle spalle!\nHan passato il torrente!\nCorron giù per la valle!\nE un turbine che passa!…","translation":"The Wells Fargo men are\npursuing him on horseback!\nAshby is with them!\nThey are all right behind him!\nThey crossed the stream!\nThey are racing down the valley!\nWhat a whirlwind they make!..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":92,"sourcePage":45,"original":"(agitando i cappelli verso i cavalieri)","translation":"(Waving hats towards the riders.)"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":93,"sourcePage":45,"original":"Guardate! Guardate!\nUrrah!… Urrah!…","translation":"Look! Look!\nHurrah!... Hurrah!..."},{"speaker":"HARRY, JOE, BELLO E MINATORI","speakerTranslation":"Harry, Joe, Bello, Miners","literalText":true,"sourceTurn":94,"sourcePage":45,"original":"Ah!","translation":"Ah!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":95,"sourcePage":45,"original":"(grido di gioia)","translation":"(A cry of joy.)"},{"speaker":"HARRY, JOE, BELLO E MINATORI","speakerTranslation":"Harry, Joe, Bello, Miners","literalText":true,"sourceTurn":96,"sourcePage":45,"original":"Via, ragazzi!…\nAlla caccia!\nAlla valle!… Alla valle!\nVia tutti! Via tutti!…","translation":"Come on, boys!\nTo the chase!\nDown to the valley!\nTo the valley! Everyone, hurry!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":97,"sourcePage":45,"original":"(Stanno per lanciarsi nuovamente, quando il galoppo lontano di un cavallo a corsa sfrenata li arresta)\n(indicando in direzione degli alberi, a sinistra)","translation":"(They are about to rush off again when the distant sound of a horse galloping at full speed stops them.\nSomeone points toward the trees on the left.)"},{"speaker":"JOE","speakerTranslation":"Joe","literalText":true,"sourceTurn":98,"sourcePage":45,"original":"È Sonora, guardate!…","translation":"It's Sonora, look!..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":99,"sourcePage":45,"original":"(da lontano)","translation":"(From far away.)"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":100,"sourcePage":45,"original":"Holla!… Holla!…","translation":"Holla!... Holla!..."},{"speaker":"JOE E MINATORI","speakerTranslation":"Joe, Miners","literalText":true,"sourceTurn":101,"sourcePage":45,"original":"Holla!… Holla!…","translation":"Holla!... Holla!..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":102,"sourcePage":45,"original":"(Fanno largo a Sonora e alcuni gli vanno incontro correndo. – Sonora entra a galoppo. Rance afferra per la briglia il cavallo e lo ferma. Sonora scende da cavallo seguito da quattro minatori)\n(afferrando Sonora per un braccio)","translation":"(They make way for Sonora and some run to meet him. He gallops in. Rance catches his horse by the bridle and stops it; Sonora dismounts, followed by four miners.\nRance seizes him by the arm.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":103,"sourcePage":45,"original":"Racconta!…","translation":"Tell us!..."},{"speaker":"HARRY, JOE, BELLO E MINATORI","speakerTranslation":"Harry, Joe, Bello, Miners","literalText":true,"sourceTurn":104,"sourcePage":45,"original":"Racconta!","translation":"Tell us!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":"104b","sourcePage":45,"original":"(con un grido strozzato)","translation":"(With a strangled cry.)"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":105,"sourcePage":45,"original":"È preso!","translation":"He's caught!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":106,"sourcePage":45,"original":"(gridando)","translation":"(Shouting.)"},{"speaker":"TUTTI","speakerTranslation":"All","literalText":true,"sourceTurn":107,"sourcePage":45,"original":"Urrah!… Urrah!…","translation":"Hurrah!... Hurrah!..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":108,"sourcePage":45,"original":"(Tutti si stringono attorno a Sonora, chiedendo notizie)","translation":"(They crowd around Sonora to hear the news.)"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":109,"sourcePage":46,"original":"(confuse)","translation":"(Confusedly.)"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":110,"sourcePage":46,"original":"Come fu?… -- Dov’è stato?\nNon l’hai visto?…\nDi’ su, presto!…","translation":"How did it happen?... Where was he?\nDidn't you see him?\nCome, tell us quickly!"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":111,"sourcePage":46,"original":"Racconta!…","translation":"Tell us!..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":112,"sourcePage":46,"original":"(fan cenni d’essere affannati dalla corsa)","translation":"(They gesture to show that running has left them breathless.)"},{"speaker":"SONORA E MINATORI","speakerTranslation":"Sonora, Miners","literalText":true,"sourceTurn":113,"sourcePage":46,"original":"L’ho veduto!. Perdio! Pareva un lupo \nstretto dai cani!… Fra poco sarà qui.","translation":"I saw him! By God, he was like a\nwolf surrounded by hounds! He will be here shortly."},{"speaker":"BELLO E MINATORI","speakerTranslation":"Bello, Miners","literalText":true,"sourceTurn":114,"sourcePage":46,"original":"Maledetto spagnuolo! \nChe ne faremo?…","translation":"Damned Spaniard! What shall we\ndo with him?"},{"speaker":"HARRY, JOE, SONORA, BELLO E MINATORI","speakerTranslation":"Harry, Joe, Sonora, Bello, Miners","literalText":true,"sourceTurn":115,"sourcePage":46,"original":"Un ottimo pendaglio!\nLo faremo ballar!","translation":"A fine fellow for the gallows!\nWe'll make him dance!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":116,"sourcePage":46,"original":"(estraendo le pistole e fingendo di sparare)","translation":"(They draw their pistols and pretend to shoot.)"},{"speaker":"HARRY, JOE, SONORA, BELLO E MINATORI","speakerTranslation":"Harry, Joe, Sonora, Bello, Miners","literalText":true,"sourceTurn":117,"sourcePage":46,"original":"E quando ballerà\nPam! Pam! \ntireremo al bersaglio!\nPam! Pam!","translation":"And when he dances,\nbang! Bang!\nWe'll use him for target practice!\nBang! Bang!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":118,"sourcePage":46,"original":"(ballando e saltando in modo selvaggio)","translation":"(Dancing and jumping savagely.)"},{"speaker":"HARRY, JOE, SONORA, BELLO E MINATORI","speakerTranslation":"Harry, Joe, Sonora, Bello, Miners","literalText":true,"sourceTurn":119,"sourcePage":46,"original":"«Dooda, dooda, dooda, dooda, day!…»\nLo faremo ballare appena arriva\nUrrah!… Urrah!… Urrah!…","translation":"“Dooda, dooda, dooda, dooda, day!” We'll make\nhim dance as soon as he arrives.\nHurrah! Hurrah! Hurrah!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":120,"sourcePage":46,"original":"(avviandosi verso il fondo della scena a sinistra)","translation":"(Moving to the back of the stage, left.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":121,"sourcePage":46,"original":"Minnie, Minnie, è finita!\nIo non fui, non parlai!\ntenni fede al divieto!…\nA che ti valse, a che ti vale, ormai?\nIl tuo bel vagheggino\ndondolerà da un albero al rovaio!","translation":"Minnie, Minnie, it is over!\nI did not act,\nI did not speak; I kept my promise of silence!\nWhat good has that done you now?\nYour handsome sweetheart will\nswing from a tree in the bitter wind!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":122,"sourcePage":46,"original":"(si siede affranto) \n(si avvicina a Billy sul davanti della scena e gli dà una manciata d’oro. Rapidamente, gridato con forza crescente)","translation":"(He sinks down,\nexhausted. Nick approaches Billy at the front and gives him a handful of gold. He speaks rapidly, growing louder.)"},{"speaker":"NICK","speakerTranslation":"Nick","literalText":true,"sourceTurn":123,"sourcePage":46,"original":"Questo è per te…\nRitarda ancora a fare il laccio…\nGuai se mi tradisci","translation":"This is for you...\nTake your time before making the noose...\nIf you betray me, beware!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":124,"sourcePage":46,"original":"(puntandogli la pistola in faccia)","translation":"(Pointing his pistol at Billy's face.)"},{"speaker":"NICK","speakerTranslation":"Nick","literalText":true,"sourceTurn":125,"sourcePage":46,"original":"In parola di Nick, bada, t’ammazzo!","translation":"I swear by Nick's word, I'll kill you!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":126,"sourcePage":46,"original":"(Nick fugge precipitosamente a destra. Compare dal fondo a sinistra Ashby, a cavallo; lo segue un cavaliere che tiene stretto, innanzi a sé sulla sella, Johnson. Il viso sconvolto e graffiato, la camicia stracciata su di una spalla, le mani legate dietro il dorso; altri tre cavalieri, colle pistole in pugno, li seguono, assieme ad alcuni minatori)","translation":"(Nick hurries away to the right. Ashby appears on horseback from the left rear. Behind him comes a rider holding Johnson in front of him in the saddle: Johnson's face is battered and scratched, his shirt torn at one shoulder, his hands bound behind his back. Three more armed riders follow, with miners.)"},{"speaker":"TRIN, HARRY, JOE, BELLO, HAPPY E MINATORI","speakerTranslation":"Trin, Harry, Joe, Bello, Happy, Miners","literalText":true,"sourceTurn":127,"sourcePage":46,"original":"A morte!… Al laccio!…\nAl laccio lo spagnuolo!\nA morte!…","translation":"Death to him!\nThe noose! Hang the Spaniard!\nDeath!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":128,"sourcePage":46,"original":"(a Rance, dal centro della scena)","translation":"(To Rance, from the middle of the stage.)"}]},{"type":"Passage","listeningLandmark":true,"routeItem":3,"originalTitle":"Sceriffo Rance!","translatedTitle":"Sheriff Rance!","threeLineOutline":true,"sourceTitlesOnly":true,"participants":["Ashby","Trin","Harry","Joe","Bello","Happy","Miners"],"turns":[{"speaker":"ASHBY","speakerTranslation":"Ashby","literalText":true,"sourceTurn":129,"sourcePage":46,"original":"Sceriffo Rance! Consegno a voi quest’uomo\nperché sia dato alla comunità.\nFaccia essa giustizia!…","translation":"Sheriff Rance! I hand this man over to you\nto be judged by the community.\nLet the people administer justice!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":130,"sourcePage":46,"original":"(I cavalieri smontano, fanno scendere di sella Johnson e lo spingono sul davanti della scena: i minatori si dispongono davanti a lui; chi è seduto sui tronchi d’alberi, chi in piedi, a gruppi, a guisa di un tribunale: Rance è a destra, sul davanti: i cavalieri appiedati nel fondo, a destra e a sinistra. Billy continua indifferente il suo gioco.)","translation":"(The riders dismount, pull Johnson from the saddle and push him downstage. The miners stand or sit on tree trunks before him in groups, like a tribunal. Rance stands at the front on the right; the riders remain at the back, right and left. Billy indifferently continues his card game.)"},{"speaker":"TRIN, HARRY, JOE, BELLO, HAPPY E MINATORI","speakerTranslation":"Trin, Harry, Joe, Bello, Happy, Miners","literalText":true,"sourceTurn":131,"sourcePage":46,"original":"La farà!…","translation":"They will do it!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":132,"sourcePage":46,"original":"(a Johnson, da fondo, mentre si allontana a cavallo)","translation":"(To Johnson from the rear, as he rides away.)"},{"speaker":"ASHBY","speakerTranslation":"Ashby","literalText":true,"sourceTurn":133,"sourcePage":46,"original":"Buona fortuna, o mio bel gentiluomo!","translation":"Good luck, my fine gentleman!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":134,"sourcePage":47,"original":"(dopo aver acceso un sigaro, si avvicina a Johnson, che è nel mezzo, isolato, e gli getta una lunga boccata di fumo in viso. Ironico)","translation":"(After lighting a cigar, Rance approaches Johnson, who stands isolated in the center, and blows a long cloud of smoke into his face with sarcasm.)"}]},{"type":"Passage","listeningLandmark":true,"routeItem":4,"originalTitle":"E così, Mister Johnson, come va?","translatedTitle":"Well, Mister Johnson, how are you?","threeLineOutline":true,"sourceTitlesOnly":true,"participants":["Rance","Johnson","Voices","Harry","Bello","Trin","Happy","Miners","Joe","Sonora"],"turns":[{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":135,"sourcePage":47,"original":"E così, Mister Johnson, come va?\nScusate se vi abbiamo disturbato…","translation":"Well, Mister Johnson, how are you?\nForgive us for disturbing you..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":136,"sourcePage":47,"original":"(sdegnoso, guardandolo fisso)","translation":"(Indignantly, staring at him.)"},{"speaker":"JOHNSON","speakerTranslation":"Johnson","literalText":true,"sourceTurn":137,"sourcePage":47,"original":"Purché facciate presto!…","translation":"Only be quick about it!"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":138,"sourcePage":47,"original":"Oh, quanto a questo bastano a sbrigarci\npochi minuti…","translation":"Oh, for that, we need only a\nfew minutes..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":139,"sourcePage":47,"original":"(indifferente)","translation":"(Indifferently.)"},{"speaker":"JOHNSON","speakerTranslation":"Johnson","literalText":true,"sourceTurn":140,"sourcePage":47,"original":"È quello che desidero.","translation":"That is exactly what I wish."},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":141,"sourcePage":47,"original":"E che desideran tutti, vero?","translation":"And what everybody wants, isn't it?"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":142,"sourcePage":47,"original":"(La turba dei minatori si stringe attorno ai due uomini con un brontolio iroso e impaziente. Il brontolio sordo che corre fra i minatori scoppia ad un tratto in un tumulto rabbioso, violentissimo. Tutti sono intorno a Johnson che li fronteggia colla sua fierezza sdegnosa e il busto eretto, la fronte aggrottata, e lo investono con gesti e voci minacciose)\n(con violenza)","translation":"(The miners crowd around the two men with angry, impatient muttering. Their low growl erupts into a furious tumult. They surround Johnson, who confronts them with proud contempt, upright and frowning, while they assail him with gestures and\nthreats.)"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":143,"sourcePage":47,"original":"Al laccio!\nA morte!\nCane!…\nFiglio di cane!… Ladro!…","translation":"To the noose!\nDeath!\nDog!\nSon of a dog! Thief!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":144,"sourcePage":47,"original":"(con accanimento, avanzandosi verso Johnson)","translation":"(Furiously advancing toward Johnson.)"},{"speaker":"HARRY","speakerTranslation":"Harry","literalText":true,"sourceTurn":145,"sourcePage":47,"original":"Hai saccheggiato \ntutto il paese!…","translation":"You have plundered\nthe whole country!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":146,"sourcePage":47,"original":"(con accanimento, avanzandosi verso Johnson)","translation":"(Furiously advancing toward Johnson.)"},{"speaker":"BELLO","speakerTranslation":"Bello","literalText":true,"sourceTurn":147,"sourcePage":47,"original":"La tua banda ladra \nha rubato ed ucciso!…","translation":"Your band of thieves\nhas robbed and killed!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":148,"sourcePage":47,"original":"(scattando)","translation":"(With a sudden outburst.)"},{"speaker":"JOHNSON","speakerTranslation":"Johnson","literalText":true,"sourceTurn":149,"sourcePage":47,"original":"No!… No!…","translation":"No! No!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":150,"sourcePage":47,"original":"(con accanimento avanzandosi verso Johnson)","translation":"(Furiously advancing toward Johnson.)"},{"speaker":"TRIN","speakerTranslation":"Trin","literalText":true,"sourceTurn":151,"sourcePage":47,"original":"La squadra \ndi Monterey, bandito,\nfu massacrata dalle faccie gialle","translation":"The men from Monterey,\nbandit,\nwere massacred by the yellow-faced ruffians"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":152,"sourcePage":47,"original":"(avvicinando la faccia a Johnson)","translation":"(Moving his face close to Johnson's.)"},{"speaker":"TRIN","speakerTranslation":"Trin","literalText":true,"sourceTurn":153,"sourcePage":47,"original":"di quelle tue canaglie messicane!…","translation":"of your Mexican gang!"},{"speaker":"HAPPY","speakerTranslation":"Happy","literalText":true,"sourceTurn":154,"sourcePage":47,"original":"Pugnalasti alle spalle \nil povero Tommy!…","translation":"You stabbed poor Tommy\nin the back!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":155,"sourcePage":47,"original":"(pallidissimo)","translation":"(Deathly pale.)"},{"speaker":"JOHNSON","speakerTranslation":"Johnson","literalText":true,"sourceTurn":156,"sourcePage":47,"original":"No! Non è vero!…","translation":"No! That is not true!"},{"speaker":"HAPPY E MINATORI","speakerTranslation":"Happy, Miners","literalText":true,"sourceTurn":157,"sourcePage":47,"original":"Si!","translation":"Yes!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":158,"sourcePage":47,"original":"(dando un pugno sul viso di Johnson)","translation":"(Punching Johnson in the face.)"},{"speaker":"HARRY","speakerTranslation":"Harry","literalText":true,"sourceTurn":159,"sourcePage":47,"original":"Non è un mese, alla valle\nfu ucciso un postiglione!","translation":"Less than a month ago a\nstagecoach driver was murdered in the valley!"},{"speaker":"BELLO","speakerTranslation":"Bello","literalText":true,"sourceTurn":160,"sourcePage":47,"original":"Tu lo uccidesti!…","translation":"You killed him!"},{"speaker":"JOHNSON","speakerTranslation":"Johnson","literalText":true,"sourceTurn":161,"sourcePage":47,"original":"No!","translation":"No!"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":162,"sourcePage":47,"original":"A morte!…","translation":"Death!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":163,"sourcePage":47,"original":"(fierissimo, alzando il capo, con gli occhi sfavillanti sotto le sopracciglia corrugate)","translation":"(With fierce pride, lifting his head, his eyes flashing beneath drawn brows.)"},{"speaker":"JOHNSON","speakerTranslation":"Johnson","literalText":true,"sourceTurn":164,"sourcePage":47,"original":"Maledizione a me!…\nFui ladro, ma assassino mai!","translation":"Curse me!\nI was a thief, but never a murderer!"},{"speaker":"JOE, BELLO E MINATORI","speakerTranslation":"Joe, Bello, Miners","literalText":true,"sourceTurn":165,"sourcePage":47,"original":"No, non è ver!…","translation":"No, that isn't true!"},{"speaker":"HARRY E MINATORI","speakerTranslation":"Harry, Miners","literalText":true,"sourceTurn":166,"sourcePage":48,"original":"Se pure, fu la sorte \nche ti aiutò!","translation":"If so, it was only\nluck that helped you!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":167,"sourcePage":48,"original":"(sommessamente, con accento drammatico)","translation":"(Quietly, in dramatic tones.)"},{"speaker":"TRIN","speakerTranslation":"Trin","literalText":true,"sourceTurn":168,"sourcePage":48,"original":"Alla “Polka” quella notte \nvenisti per rubare…","translation":"That night at the Polka\nyou came to steal..."},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":169,"sourcePage":48,"original":"Furon gli occhi e il sorriso \ndi Minnie, a disarmarti!…","translation":"Minnie's eyes and\nsmile disarmed you!"},{"speaker":"BELLO","speakerTranslation":"Bello","literalText":true,"sourceTurn":170,"sourcePage":48,"original":"Anche lei ci hai rubato!","translation":"You have stolen her from us too!"},{"speaker":"HARRY","speakerTranslation":"Harry","literalText":true,"sourceTurn":171,"sourcePage":48,"original":"Ladro! Ladro!","translation":"Thief! Thief!"},{"speaker":"BELLO","speakerTranslation":"Bello","literalText":true,"sourceTurn":172,"sourcePage":48,"original":"Ladro d’oro \ne di ragazze!","translation":"A thief of\ngold and girls!"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":173,"sourcePage":48,"original":"Al laccio lo spagnuolo!\nA morte!… A morte!…\nBilly ha la mano maestra!…\nE sarai fatto re della foresta!…\nA morte!","translation":"Hang the Spaniard! Death!\nDeath! Billy knows how\nto make a noose!\nYou'll be crowned king of the forest!\nDeath!"},{"speaker":"TRIN, HARRY, JOE E MINATORI","speakerTranslation":"Trin, Harry, Joe, Miners","literalText":true,"sourceTurn":174,"sourcePage":48,"original":"Ti faremo ballare \nl’ultima contraddanza…","translation":"We'll make you\ndance your last country dance..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":175,"sourcePage":48,"original":"(Tutti si stringono, rabbiosi, intorno a Johnson, cosicché egli appare sommerso fra quella gente infuriata)","translation":"(They press angrily around Johnson until he seems buried beneath the furious crowd.)"},{"speaker":"SONORA, BELLO, HAPPY E MINATORI","speakerTranslation":"Sonora, Bello, Happy, Miners","literalText":true,"sourceTurn":176,"sourcePage":48,"original":"Ti faremo scontare \nle carezze di Minnie…","translation":"We'll make you\npay for Minnie's caresses..."},{"speaker":"MINATORI","speakerTranslation":"Miners","literalText":true,"sourceTurn":177,"sourcePage":48,"original":"Ti faremo cantare la romanza\ndella “Bella fanciulla”!…\nSarai fatto re della foresta!…\nA morte!","translation":"We'll make you sing the ballad\nof the “Beautiful Girl”!\nYou'll be crowned king of the forest!\nDeath!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":178,"sourcePage":48,"original":"(scostando i più accaniti, avvicinandosi a Johnson e battendogli un mano sulla spalla, con fare ironico))","translation":"(Rance pushes the fiercest men aside, comes up to Johnson and taps his shoulder mockingly.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":179,"sourcePage":48,"original":"Non vi preoccupate, caballero!\nÈ una cosa da nulla…","translation":"Don't worry, caballero!\nIt's nothing at all..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":180,"sourcePage":48,"original":"(La turba si scosta, cosicché Johnson rimane ancora isolato nel mezzo)\n(con fierezza ed esaltandosi)","translation":"(The crowd moves aside, leaving Johnson isolated once more. He speaks proudly,\nwith mounting exaltation.)"}]},{"type":"Passage","listeningLandmark":true,"routeItem":5,"originalTitle":"Risparmiate lo scherno","translatedTitle":"Spare me your mockery","threeLineOutline":true,"sourceTitlesOnly":true,"participants":["Johnson","Rance","Voices","Sonora"],"turns":[{"speaker":"JOHNSON","speakerTranslation":"Johnson","literalText":true,"sourceTurn":181,"sourcePage":48,"original":"Risparmiate lo scherno… Della morte… \nnon mi metto pensiero: e ben voi tutti \nlo sapete!","translation":"Spare me your mockery...\nDeath does not frighten me, and you all know\nit well!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":182,"sourcePage":48,"original":"(con sprezzo altezzoso)","translation":"(With haughty disdain.)"},{"speaker":"JOHNSON","speakerTranslation":"Johnson","literalText":true,"sourceTurn":183,"sourcePage":48,"original":"Pistola o laccio è uguale…\nSe mi sciogliete un braccio,\nmi sgozzo di mia mano!\nD’altro voglio parlarvi:","translation":"Pistol or rope, it is all the same...\nFree one of my arms and\nI'll cut my own throat!\nI want to speak of something else:"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":184,"sourcePage":48,"original":"(con grande sentimento)","translation":"(With deep feeling.)"},{"speaker":"JOHNSON","speakerTranslation":"Johnson","literalText":true,"sourceTurn":185,"sourcePage":48,"original":"della donna ch’io amo…","translation":"of the woman I love..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":186,"sourcePage":48,"original":"(Un mormorio di sorpresa serpeggia fra la folla dei minatori)\n(con scatto, guardando l’orologio)","translation":"(An astonished murmur passes through the miners.\nRance glances abruptly at his watch.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":187,"sourcePage":48,"original":"Hai due minuti per amarla ancora…","translation":"You have two minutes left to love her..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":188,"sourcePage":48,"original":"(mormorato sommesso)","translation":"(Murmured in low voices.)"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":189,"sourcePage":48,"original":"Basta, perdio!\nFatelo star zitto!…\nChe sfacciato, basta!","translation":"Enough, damn it!\nMake him be quiet!\nWhat impudence! Enough!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":190,"sourcePage":48,"original":"(con accento represso d’ira)","translation":"(With suppressed anger.)"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":191,"sourcePage":48,"original":"Basta!\nAlla corda!\nFatelo star zitto!\nParlerà da quel ramo!…","translation":"Enough!\nTo the rope!\nShut him up!\nHe'll speak from that branch!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":192,"sourcePage":48,"original":"(con autorità, dominando il tumulto)","translation":"(With authority, mastering the uproar.)"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":193,"sourcePage":48,"original":"Lasciatelo parlare!","translation":"Let him speak!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":194,"sourcePage":48,"original":"(tutti tacciono)","translation":"(Everyone falls silent.)"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":195,"sourcePage":49,"original":"È nel suo dritto!…","translation":"It is his right!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":196,"sourcePage":49,"original":"(Si fa accanto a Johnson e lo guarda fisso, combattuto fra l’odio, l’ammirazione e la gelosia.)\n(sorpreso)","translation":"(Sonora approaches Johnson and stares at him, torn between hatred, admiration and jealousy.\nJohnson is surprised.)"},{"speaker":"JOHNSON","speakerTranslation":"Johnson","literalText":true,"sourceTurn":197,"sourcePage":49,"original":"Ti ringrazio, Sonora!…","translation":"Thank you, Sonora!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":198,"sourcePage":49,"original":"(rivolto a tutti)","translation":"(Addressing them all.)"},{"speaker":"JOHNSON","speakerTranslation":"Johnson","literalText":true,"sourceTurn":199,"sourcePage":49,"original":"Per lei, per lei soltanto,\nche tutti amate,\na voi chiedo una grazia e una promessa…\nCh’ella non sappia mai come son morto!","translation":"For her, for her alone,\nwhom you all love,\nI ask one favor and one promise:\nnever let her know how I died!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":200,"sourcePage":49,"original":"(mormorii sommessi)\n(guardando l’orologio, nervoso)","translation":"(Quiet murmurs.\nRance looks nervously at his watch.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":201,"sourcePage":49,"original":"Un minuto… sii breve.","translation":"One minute... be brief."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":202,"sourcePage":49,"original":"(con grande espressione, esaltandosi, col viso quasi sorridente)","translation":"(With great emotion, passionately, almost smiling.)"}]},{"type":"Passage","listeningLandmark":true,"routeItem":6,"originalTitle":"Ch’ella mi creda libero e lontano","translatedTitle":"Let her believe me free and far away","threeLineOutline":true,"sourceTitlesOnly":true,"participants":["Johnson","Rance","Miners"],"turns":[{"speaker":"JOHNSON","speakerTranslation":"Johnson","literalText":true,"sourceTurn":203,"sourcePage":49,"original":"Ch’ella mi creda libero e lontano,\nsopra una nuova via di redenzione!…\nAspetterà ch’io torni…\nE passeranno i giorni…\ned io non tornerò…\nMinnie, della mia vita mio solo fiore,","translation":"Let her believe me free and far away,\non a new road toward redemption!\nShe will wait for my return...\nAnd the days will pass...\nBut I shall never come back...\nMinnie, the only flower of my life,"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":204,"sourcePage":49,"original":"(Mormorio sdegnoso)","translation":"(An indignant murmur.)"},{"speaker":"JOHNSON","speakerTranslation":"Johnson","literalText":true,"sourceTurn":205,"sourcePage":49,"original":"Minnie, che m’hai voluto tanto bene!…\nAh! tu della mia vita mio solo fior!","translation":"Minnie, who loved me so dearly! Ah,\nyou, the only flower of my life!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":206,"sourcePage":49,"original":"(si slancia su Johnson, lo colpisce con un pugno sul viso)","translation":"(Rance lunges at Johnson and punches him in the face.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":207,"sourcePage":49,"original":"Ah, sfacciato!…","translation":"Ah, insolent scoundrel!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":208,"sourcePage":49,"original":"(disapprovando Rance)","translation":"(Disapproving of Rance.)"},{"speaker":"MINATORI","speakerTranslation":"Miners","literalText":true,"sourceTurn":209,"sourcePage":49,"original":"Uh!… Uh!… Uh!…","translation":"Ooh! Ooh! Ooh!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":210,"sourcePage":49,"original":"(a Johnson)","translation":"(To Johnson.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":211,"sourcePage":49,"original":"Hai null’altro \nda dire?…","translation":"Have you anything more\nto say?"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":212,"sourcePage":49,"original":"(con alterigia)","translation":"(Haughtily.)"},{"speaker":"JOHNSON","speakerTranslation":"Johnson","literalText":true,"sourceTurn":213,"sourcePage":49,"original":"Nulla. Andiamo!","translation":"Nothing. Let's go!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":214,"sourcePage":49,"original":"(Rance va verso il fondo per cercare l’albero al quale sarà appiccato Johnson: lo seguono alcuni minatori. – Rance indica colla mano l’albero scelto: la turba si muove tutta, ondeggiando, verso quel punto. – Sonora rotola un sasso sino a portarlo sotto l’albero, poi si avvicina a johnson, lo tocca su di una spalla; Johnson si avvia con passo sicuro verso l’albero, sale sopra il sasso e calmo, stoico, attende il proprio destino. Rance vede Billy seduto a terra; gli si avvicina e con un calcio lo obbliga ad alzarsi. Billy si alza, tenendo il laccio in una mano e si avvia verso l’albero; Sonora gli strappa dalle mani il laccio, respinge brutalmente Billy, e poi getta il laccio ad un minatore che è salito sull’albero e si è messo a cavalcioni su di un ramo; il minatore lascia penzolare il laccio che viene posto al collo di Johnson e getta l’altro lato della corda a terra: questa viene afferrata da tre minatori che si accingono ad impiccare Johnson – gli altri gli sono d’intorno: alcuni hanno impugnato le pistole e le appuntano verso Johnson. Billy è tornato a sedersi e ripiglia il suo giuoco, fumando la pipa. – Un grido acutissimo giunge da destra col rumore sordo di un galoppo. – Tutti si fermano e si volgono: i tre minatori che stavano per impiccar Johnson lasciano la corda e corrono verso il fondo a destra; altri minatori li seguono sorpresi; il minatore a cavalcioni del ramo scende pure a terra.)\n(con grido selvaggio)","translation":"(Rance searches for a tree from which Johnson can be hanged. Some miners follow and he points to the chosen tree. The crowd surges toward it. Sonora rolls a stone beneath the tree and touches Johnson's shoulder. Johnson walks steadily over and stands on the stone, awaiting his fate. Rance kicks Billy, who is sitting nearby, and makes him rise with the rope. Sonora takes the rope from Billy and throws it to a miner astride a branch. A noose is lowered around Johnson's neck, and the other end of the rope is taken by three miners. Armed men surround him, their pistols drawn. Billy goes back to his cards. Suddenly a shrill cry is heard on the right, with the sound of a galloping horse. Everyone stops and turns, the men holding the rope let it go, and the miner in the tree\nclimbs down.)"}]},{"type":"Passage","listeningLandmark":true,"routeItem":7,"originalTitle":"Ah! Ah! Ah!… È Minnie!","translatedTitle":"Ah! Ah! Ah!… It is Minnie!","threeLineOutline":true,"sourceTitlesOnly":true,"participants":["Minnie","Voices","Rance","Sonora"],"turns":[{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":215,"sourcePage":49,"original":"Ah! Ah! Ah!…","translation":"Ah! Ah! Ah!"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":216,"sourcePage":49,"original":"È Minnie!… È Minnie!… È Minnie!…","translation":"It's Minnie! It's Minnie! It's Minnie!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":217,"sourcePage":49,"original":"(Scena confusa. Tutti guardano verso il fondo da dove apparirà Minnie a cavallo)\n(slanciandosi verso Johnson e gridando come un forsennato)","translation":"(A confused scene. All look toward the back, where Minnie will appear on horseback.\nRance rushes at Johnson and shouts like a madman.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":218,"sourcePage":49,"original":"Impiccatelo!…","translation":"Hang him!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":219,"sourcePage":49,"original":"(Nessuno bada a Rance. Tutti si agitano per l’arrivo di Minnie)","translation":"(No one listens to Rance; all are agitated by Minnie's arrival.)"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":220,"sourcePage":50,"original":"(slanciandosi a destra e a sinistra incitando la folla)","translation":"(Rance runs from side to side, urging the crowd on.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":221,"sourcePage":50,"original":"Impiccatelo!…","translation":"Hang him!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":222,"sourcePage":50,"original":"(Minnie arriva in scena a cavallo, discinta, i capelli al vento, scende, corre verso il gruppo che circonda Johnson, afferra la corda abbandonata dai tre minatori e si pone davanti a Johnson, difendendolo col proprio corpo. – La folla dei minatori si ritrae, Johnson rimane immobile col laccio al collo).","translation":"(Minnie gallops onstage, her clothing disordered and hair flying. She dismounts, runs to the group around Johnson, seizes the rope abandoned by the three miners and places herself in front of him, shielding him with her body. The miners retreat; Johnson stands motionless with the noose around his neck.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":223,"sourcePage":50,"original":"Impiccatelo!…\nAh!","translation":"Hang him!...\nAh!"},{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":224,"sourcePage":50,"original":"Ah, no!… Chi l’oserà?","translation":"Ah, no! Who would dare?"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":225,"sourcePage":50,"original":"(facendolesi innanzi)","translation":"(Confronting her.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":226,"sourcePage":50,"original":"La giustizia lo vuol!","translation":"Justice demands it!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":227,"sourcePage":50,"original":"(fronteggiandolo)","translation":"(Facing him.)"},{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":228,"sourcePage":50,"original":"E di quale giustizia parli tu,\nvecchio bandito?","translation":"And what justice are you talking about,\nyou old bandit?"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":229,"sourcePage":50,"original":"(fa segno di minaccia e s’avvicina a Minnie)","translation":"(Rance makes a threatening gesture and approaches Minnie.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":230,"sourcePage":50,"original":"Bada, \ndonna, alle tue parole!","translation":"Watch your words,\nwoman!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":231,"sourcePage":50,"original":"(guardandolo negli occhi)","translation":"(Looking him in the eyes.)"},{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":232,"sourcePage":50,"original":"Che puoi farmi? Non ti temo!…\nAh!","translation":"What can you do to me? I am not afraid of you!\nAh!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":233,"sourcePage":50,"original":"(Qualcuno dei minatori risolutamente si avvicina a Johnson. Minnie d’un balzo si pone dinanzi a Johnson spianando la pistola. I minatori si ritraggono; un altro gruppo di minatori si avanza minaccioso, ma indietreggia davanti alla pistola spianata da Minnie)\n(incitando la folla)","translation":"(Some miners resolutely approach Johnson. Minnie leaps in front of him and points her pistol. They retreat. Another group advances threateningly, but backs away before Minnie's drawn weapon. Rance urges the\ncrowd on.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":234,"sourcePage":50,"original":"Strappatela di là!\nNessun di voi\nha sangue nelle vene?","translation":"Drag her away!\nHas none of you\nany blood in his veins?"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":235,"sourcePage":50,"original":"(La turba non si muove, come affascinata dallo sguardo di Minnie)","translation":"(The crowd does not move, spellbound by Minnie's gaze.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":236,"sourcePage":50,"original":"Una gonna vi fa sbiancare il viso?","translation":"Does a skirt make you turn pale?"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":237,"sourcePage":50,"original":"(incitando sempre la folla)","translation":"(Still inciting the crowd.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":238,"sourcePage":50,"original":"Strappatela di là!","translation":"Drag her away!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":239,"sourcePage":50,"original":"(cercando di spingere alcuni verso Minnie)","translation":"(Trying to push some men towards Minnie.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":240,"sourcePage":50,"original":"Orsù!…","translation":"Come on!"},{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":241,"sourcePage":50,"original":"Avanti!…","translation":"Come on, then!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":242,"sourcePage":50,"original":"(Si stringe più accanto a Johnson, appoggia il viso sulla sua spalla continuando a fissare la turba con uno sguardo di sfida, sempre spianando la pistola)\n(come pazzo di rabbia)","translation":"(She presses closer to Johnson and rests her face on his shoulder, still pointing her pistol and defiantly staring at the crowd.\nRance is beside himself with rage.)"},{"speaker":"RANCE","speakerTranslation":"Rance","literalText":true,"sourceTurn":243,"sourcePage":50,"original":"Finiamola! Bisogna\nche giustizia sia fatta!","translation":"Let's end this!\nJustice must be done!"},{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":244,"sourcePage":50,"original":"Osate!…","translation":"Just dare!"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":245,"sourcePage":50,"original":"Basta!..- Al laccio!…","translation":"Enough!... To the noose!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":246,"sourcePage":50,"original":"(La turba, esaltandosi a poco a poco si stringe attorno a Minnie e a Johnson. – La turba, ripresa dal suo furore d’odio e di gelosia, si avanza più minacciosa. – Due degli uomini armati che fiancheggiano l’albero, afferrano Minnie alle spalle: essa si divincola e si aggrappa ancora a Johnson alzando rapidamente la pistola)","translation":"(The crowd, increasingly excited, closes around Minnie and Johnson. Reviving their jealous fury, the men press more threateningly. Two armed miners by the tree seize Minnie from behind. She struggles free and clings again to Johnson, quickly raising her pistol.)"},{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":247,"sourcePage":50,"original":"Lasciatemi, o l’uccido, \ne m’uccido!","translation":"Let me go or I shall kill\nhim and kill myself!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":248,"sourcePage":50,"original":"(con un grido, gettandosi fra lei e la turba)","translation":"(With a cry, Sonora throws himself between her and the crowd.)"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":249,"sourcePage":50,"original":"Lasciatela!--. Lasciatela!.-- Lasciatela!","translation":"Let her go! Let her go! Let her go!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":250,"sourcePage":50,"original":"(Tutti si ritraggono. Rance, pallido e torvo, si discosta e si siede sul tronco d’albero presso al fuoco. Sonora rimane in piedi presso Minnie e Johnson, minaccioso)","translation":"(Everyone draws back. Pale and grim, Rance withdraws and sits on the log beside the fire. Sonora stands protectively by Minnie and Johnson, threatening the others.)"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":251,"sourcePage":51,"original":"(pallidissima, tremante di sdegno, la voce sibilante)","translation":"(Deathly pale, trembling with indignation, her voice hissing.)"}]},{"type":"Passage","listeningLandmark":true,"routeItem":8,"originalTitle":"Non vi fu mai chi disse «Basta!»","translatedTitle":"No one ever cried “Enough!”","threeLineOutline":true,"sourceTitlesOnly":true,"participants":["Minnie","Sonora","Voices"],"turns":[{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":252,"sourcePage":51,"original":"Non vi fu mai chi disse\n«Basta!» quando per voi\ndavo i miei giovani anni…","translation":"None of you ever\ncried “Enough!” when I\ngave you my young years..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":253,"sourcePage":51,"original":"(con amarezza e risentimento)","translation":"(With bitterness and resentment.)"},{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":254,"sourcePage":51,"original":"quando, perduta fra bestemmie e risse,\ndividevo gli affanni\ne i disagi con voi… Nessuno ha detto\nallora «Basta!».","translation":"when, surrounded by curses and quarrels,\nI shared your\ntroubles and hardships... No one cried\n“Enough!” then."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":255,"sourcePage":51,"original":"(La turba tace colpita. Molti abbassano il capo)","translation":"(The crowd falls silent, shaken; many lower their heads.)"},{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":256,"sourcePage":51,"original":"Ora quest’uomo è mio \ncom’è di Dio!\nDio nel ciel l’aveva benedetto!\nSe ne andava lontano, \nverso nuovi orizzonti!..,\nIl bandito che fu\nè già morto lassù, sotto il mio tetto.\nVoi non potete ucciderlo!\nNo!","translation":"Now this man belongs to me,\njust as\nhe belongs to God! God in heaven\nhad blessed him!\nHe was going far away, toward new horizons!\nThe bandit he\nonce was is already dead, up there beneath my roof.\nYou cannot kill him!\nNo!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":257,"sourcePage":51,"original":"(Una commozione rude comincia ad impadronirsi di tutti gli animi. Nessuno più protesta)\n(con un grido che pare un singhiozzo)","translation":"(A rough emotion begins to seize every heart. Nobody protests any longer.\nSonora cries out, almost sobbing.)"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":258,"sourcePage":51,"original":"Ah, Minnie, più dell’oro \nci ha rubato, il tuo cuore!…","translation":"Ah, Minnie, he has stolen from us\nmore than gold: he has stolen your heart!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":259,"sourcePage":51,"original":"(dolcemente, con affetto)","translation":"(Gently, affectionately.)"},{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":260,"sourcePage":51,"original":"Il mio Sonora buono,\nsarà primo al perdono…","translation":"My dear good Sonora will\nbe the first to forgive..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":261,"sourcePage":51,"original":"(soggiogato, commosso, abbassa gli occhi)","translation":"(Overcome with emotion, he lowers his eyes.)"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":262,"sourcePage":51,"original":"Minnie!","translation":"Minnie!"},{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":263,"sourcePage":51,"original":"Perdonerai\ncome perdonerete tutti…","translation":"You will forgive,\nas you all will forgive..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":264,"sourcePage":51,"original":"(commossi e a testa bassa)","translation":"(Moved, with bowed heads.)"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":265,"sourcePage":51,"original":"No! \nNon possiamo!…","translation":"No!\nWe cannot!"},{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":266,"sourcePage":51,"original":"Si può ciò che si vuole!","translation":"We can do what we truly will!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":267,"sourcePage":51,"original":"(va verso Joe)","translation":"(Going to Joe.)"}]},{"type":"Passage","listeningLandmark":true,"routeItem":9,"originalTitle":"E anche tu lo vorrai, Joe","translatedTitle":"And you too will wish it, Joe","threeLineOutline":true,"sourceTitlesOnly":true,"participants":["Minnie","Sonora","Happy","Voices"],"turns":[{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":268,"sourcePage":51,"original":"E anche tu lo vorrai, \nJoe… Non sei tu che m’offrivi i fiori,\nsimili a quelli delle tue brughiere?","translation":"And you will wish it too,\nJoe... Were you not the one who brought me flowers,\nlike those from your native moors?"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":269,"sourcePage":51,"original":"(rivolgendosi a Harry, accarezzandogli la mano)","translation":"(Turning to Harry and caressing his hand.)"},{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":270,"sourcePage":51,"original":"Harry, e tu, quante sere\nt’ho vegliato morente…\ne nel delirio credevi vedere\nla tua piccola Maud,","translation":"Harry, and you—how many evenings I\nwatched over you as you lay dying...\nIn your delirium you thought\nyou saw your little Maud,"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":271,"sourcePage":51,"original":"(Harry si pone una mano sul viso e piange)","translation":"(Harry covers his face with his hand and weeps.)"},{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":272,"sourcePage":51,"original":"la sorella che adori,\nvenuta di lontano…","translation":"your beloved sister,\ncome from far away..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":273,"sourcePage":51,"original":"(a Trin con dolcezza)","translation":"(Gently, to Trin.)"},{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":274,"sourcePage":51,"original":"E tu mio Trin, a cui ressi la mano\nquando scrivevi\nle prime incerte lettere,\nche partivan di qui per San Domingo…","translation":"And you, my Trin, whose hand I\nsteadied when you\nwrote your first uncertain letters,\nto be sent from here to San Domingo..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":275,"sourcePage":51,"original":"(rivolgendosi a Happy, poi a Bello, accarezzandolo alla guancia)","translation":"(Turning to Happy, then stroking Bello's cheek.)"},{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":276,"sourcePage":51,"original":"E tu, buon Happy, e tu,\nBello, che hai gli occhi ceruli d’un bimbo,","translation":"And you, good Happy,\nand you, Bello, with eyes as blue as a child's,"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":277,"sourcePage":51,"original":"(rivolgendosi a tutti)","translation":"(Addressing everyone.)"},{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":278,"sourcePage":51,"original":"e voi tutti, fratelli del mio cuore, \nanime rudi e buone…","translation":"and all of you, brothers of my heart,\nrough and kindly souls..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":279,"sourcePage":51,"original":"(gettando via la pistola)","translation":"(Throwing away her pistol.)"},{"speaker":"MINNIE","speakerTranslation":"Minnie","literalText":true,"sourceTurn":280,"sourcePage":51,"original":"Ecco, getto quest’arma! Torno quella\nche fui per voi, l’amica, la sorella\nche un giorno v’insegnò\nuna suprema verità d’amore!\nFratelli, non v’è al mondo peccatore\ncui non s’apra una via di redenzione!","translation":"Look, I cast away this weapon!\nI become again what I was to you:\nthe friend, the sister who\nonce taught you a supreme\ntruth of love! Brothers, no sinner in the\nworld is denied a path to redemption!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":281,"sourcePage":51,"original":"(a un gruppo di minatori)","translation":"(To a group of miners.)"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":282,"sourcePage":51,"original":"È necessario…\nTroppo le dobbiamo!","translation":"It must be done...\nWe owe her too much!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":283,"sourcePage":51,"original":"(ad un minatore)","translation":"(To one miner.)"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":284,"sourcePage":51,"original":"Deciditi anche tu!","translation":"You too, make up your mind!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":285,"sourcePage":52,"original":"(scuotendo la testa)","translation":"(Shaking his head.)"},{"speaker":"HAPPY","speakerTranslation":"Happy","literalText":true,"sourceTurn":286,"sourcePage":52,"original":"Non possiam!","translation":"We cannot!"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":287,"sourcePage":52,"original":"Non possiam!","translation":"We cannot!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":288,"sourcePage":52,"original":"(ad Happy)","translation":"(To Happy.)"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":289,"sourcePage":52,"original":"Tu taci!","translation":"You be quiet!"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":290,"sourcePage":52,"original":"Non possiam!","translation":"We cannot!"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":291,"sourcePage":52,"original":"È nel suo diritto!\nÈ necessario…","translation":"It is his right!\nIt must be done..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":292,"sourcePage":52,"original":"(a Sonora)","translation":"(To Sonora.)"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":293,"sourcePage":52,"original":"E Ashby che dirà.?\nNo, non possiam!","translation":"And what will Ashby say?\nNo, we cannot!"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":294,"sourcePage":52,"original":"Dirà quel che vorrà!\nI padroni siam noi!","translation":"He may say what he likes!\nWe are the masters here!"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":295,"sourcePage":52,"original":"Non possiam!","translation":"We cannot!"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":296,"sourcePage":52,"original":"Andiamo!","translation":"Come on!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":297,"sourcePage":52,"original":"(investendo un minatore)","translation":"(Confronting a miner.)"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":298,"sourcePage":52,"original":"Non t’opporre, tu.","translation":"Don't stand in the way, you!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":299,"sourcePage":52,"original":"(ad altri)","translation":"(To others.)"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":300,"sourcePage":52,"original":"Andiamo, ragazzi!","translation":"Come on, boys!"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":301,"sourcePage":52,"original":"No, no!\nÈ una viltà!","translation":"No, no!\nIt would be cowardly!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":302,"sourcePage":52,"original":"(ad un altro gruppo)","translation":"(To another group.)"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":303,"sourcePage":52,"original":"È necessario…","translation":"It must be done..."},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":304,"sourcePage":52,"original":"No, non possiam!","translation":"No, we cannot!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":305,"sourcePage":52,"original":"(ad uno solo)","translation":"(To one man.)"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":306,"sourcePage":52,"original":"Non t’opporre, tu!","translation":"Do not oppose us!"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":307,"sourcePage":52,"original":"Per rispetto a Rance…\nNon possiamo!","translation":"Out of respect for Rance...\nWe cannot!"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":308,"sourcePage":52,"original":"Deciditi anche tu.","translation":"Make up your mind too."},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":309,"sourcePage":52,"original":"È una viltà!\nNon possiamo!","translation":"It would be cowardly!\nWe cannot!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":310,"sourcePage":52,"original":"(ad alcuni)","translation":"(To some of them.)"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":311,"sourcePage":52,"original":"Andiamo!","translation":"Come on!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":312,"sourcePage":52,"original":"(stringendosi nelle spalle)","translation":"(Shrugging their shoulders.)"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":313,"sourcePage":52,"original":"Tu lo vuoi…\nNon possiamo, no, no!\nNon si può resistere!\nRideran di noi!","translation":"You want it...\nWe cannot, no, no!\nOne cannot resist!\nThey will laugh at us!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":314,"sourcePage":52,"original":"(ad uno)","translation":"(To one of them.)"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":315,"sourcePage":52,"original":"Anche tu, su, via!\nAnche tu!\nM’han fatto piangere!\nPer me, lo fate!","translation":"You too, come on!\nYou too!\nThey made me cry!\nDo it for me!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":316,"sourcePage":52,"original":"(ad un gruppo di uomini)","translation":"(To a group of men.)"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":317,"sourcePage":52,"original":"Guardate come l’ama!","translation":"Look how he loves her!"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":318,"sourcePage":52,"original":"E come è bella!\nÈ una viltà…","translation":"And how beautiful she is!\nIt would be cowardly..."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":319,"sourcePage":52,"original":"(I minatori, con moti espressivi assentono)","translation":"(The miners show by their gestures that they agree.)"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":320,"sourcePage":52,"original":"Resister non possiam, no!…","translation":"We cannot resist any longer, no!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":321,"sourcePage":52,"original":"(ad un gruppo di minatori)","translation":"(To a group of miners.)"},{"speaker":"VOCI","speakerTranslation":"Voices","literalText":true,"sourceTurn":322,"sourcePage":53,"original":"Minnie merita tutto!…","translation":"Minnie deserves everything!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":323,"sourcePage":53,"original":"(Sonora va all’albero e scioglie Johnson dal laccio e dalla corda che gli legava le braccia. Johnson cade in ginocchio, commosso, vicino a Minnie, mentre essa pone la mano sulla testa di lui quasi benedicendolo)\n(si avanza verso Minnie; a Minnie con voce commossa)","translation":"(Sonora goes to the tree and frees Johnson from the noose and the rope binding his arms. Deeply moved, Johnson falls to his knees beside Minnie, who lays her hand on his head as\nthough blessing him. Sonora approaches Minnie, speaking with emotion.)"}]},{"type":"Passage","listeningLandmark":true,"routeItem":10,"originalTitle":"Le tue parole sono di Dio","translatedTitle":"Your words come from God","threeLineOutline":true,"sourceTitlesOnly":true,"participants":["Sonora","Johnson","Miners","Minnie"],"turns":[{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":324,"sourcePage":53,"original":"Le tue parole sono \ndi Dio. Tu l’ami come \nnessuno al mondo!…\nIn nome di tutti, \nio te lo dono.","translation":"Your words come from God.\nYou love him as no one\nelse in the world could!\nIn everyone's name,\nI give him to you."},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":325,"sourcePage":53,"original":"(si rialza e stringe le mani di Sonora nelle sue; commosso)","translation":"(Johnson rises, takes Sonora's hands in his own, deeply moved.)"},{"speaker":"JOHNSON","speakerTranslation":"Johnson","literalText":true,"sourceTurn":326,"sourcePage":53,"original":"Grazie, fratelli!","translation":"Thank you, brothers!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":327,"sourcePage":53,"original":"(piangendo)","translation":"(Weeping.)"},{"speaker":"SONORA","speakerTranslation":"Sonora","literalText":true,"sourceTurn":328,"sourcePage":53,"original":"Va’, Minnie, addio!","translation":"Go, Minnie, farewell!"},{"speaker":"MINATORI","speakerTranslation":"Miners","literalText":true,"sourceTurn":329,"sourcePage":53,"original":"Mai più ritornerai,\nno, mai più, mai più!","translation":"You will never come back,\nno, never, never!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":330,"sourcePage":53,"original":"(Minnie abbraccia Sonora, poi stringe la mano a qualche minatore; vede Nick, che è entrato in scena da qualche tempo ed ha seguito l’azione commosso; vorrebbe salutarlo – ma Nick cade a terra, ai piedi di Minnie, singhiozzando – questa si china su di lui, gli accarezza la testa, poi si avvicina a Johnson e si abbraccia a lui.)","translation":"(Minnie embraces Sonora and shakes hands with some miners. She sees Nick, who has been watching, deeply affected, and tries to say goodbye, but he falls sobbing at her feet. She bends over him, caresses his head, then approaches Johnson and embraces him.)"},{"speaker":"MINNIE E JOHNSON","speakerTranslation":"Minnie, Johnson","literalText":true,"sourceTurn":331,"sourcePage":53,"original":"Addio, mia dolce terra,\naddio, mia California!","translation":"Farewell, my sweet homeland,\nfarewell, my California!"},{"speaker":"MINATORI","speakerTranslation":"Miners","literalText":true,"sourceTurn":332,"sourcePage":53,"original":"No, mai più, no!\nritornerai!…\nAddio!… mai più!","translation":"No,\nnever again will you return!\nFarewell! Never again!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":333,"sourcePage":53,"original":"(Minnie è abbracciata a Johnson)","translation":"(Minnie embraces Johnson.)"},{"speaker":"MINNIE E JOHNSON","speakerTranslation":"Minnie, Johnson","literalText":true,"sourceTurn":334,"sourcePage":53,"original":"Addio, mia dolce terra,\naddio, mia California!","translation":"Farewell, my sweet homeland,\nfarewell, my California!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":335,"sourcePage":53,"original":"(si avviano)","translation":"(They set out.)"},{"speaker":"MINNIE E JOHNSON","speakerTranslation":"Minnie, Johnson","literalText":true,"sourceTurn":336,"sourcePage":53,"original":"Bei monti della Sierra,\nnevi, addio!","translation":"Beautiful mountains of the Sierra,\nfarewell, you snows!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":337,"sourcePage":53,"original":"(sottovoce, con grande melanconia)","translation":"(Softly, with profound sorrow.)"},{"speaker":"MINATORI","speakerTranslation":"Miners","literalText":true,"sourceTurn":338,"sourcePage":53,"original":"Mai più ritornerai!…\nmai più!…","translation":"You will never come back!\nNever again!"},{"speaker":"Stage direction","speakerTranslation":"Stage direction","literalText":true,"sourceTurn":339,"sourcePage":53,"original":"(La turba è accasciata. Alcuni sono a terra e piangono, altri appoggiati ai loro cavalli ed altri agli alberi, si abbandonano al dolore – altri ancora, tristamente, fanno cenni di addio a Minnie che va allontanandosi: Sonora si lascia cadere su un tronco d’albero e scoppia in dirotto pianto: Billy è indifferente a questa scena di commozione e continua il giuoco, calmo, freddo.)\n(allontanandosi)","translation":"(The crowd is overcome. Some lie on the ground weeping, others lean against their horses or the trees, lost in sorrow. Others sadly wave farewell as Minnie goes away. Sonora falls upon a log and bursts into tears, while Billy remains indifferent, calmly continuing his\ncard game.)"},{"speaker":"MINNIE E JOHNSON","speakerTranslation":"Minnie, Johnson","literalText":true,"sourceTurn":340,"sourcePage":53,"original":"Addio, mia California, addio…","translation":"Farewell, my California, farewell..."},{"speaker":"MINATORI","speakerTranslation":"Miners","literalText":true,"sourceTurn":341,"sourcePage":53,"original":"Mai più… mai più…","translation":"Never again... never again..."},{"speaker":"MINNIE E JOHNSON","speakerTranslation":"Minnie, Johnson","literalText":true,"sourceTurn":342,"sourcePage":53,"original":"Addio, addio, addio!…","translation":"Farewell, farewell, farewell!..."}]}]}];